def unique_json_values(values: list[dict[str, Any]]) -> list[dict[str, Any]]:
    keyed = {json.dumps(value, sort_keys=True, separators=(",", ":"), default=str): value for value in values}
    return [keyed[key] for key in sorted(keyed)]


