	if got := tokens[0]; got.In != 100 || got.Out != 50 {
		t.Fatalf("first Tokens = %#v, want In=100 Out=50", got)
	}
	if got := tokens[1]; got.In != 300 || got.Out != 80 {
		t.Fatalf("final Tokens = %#v, want In=300 Out=80", got)
